import{_ as d,c as r,a as o,o as a}from"./index-B3LiEHuY.js";const e={};function i(s,t){return a(),r("section",null,[...t[0]||(t[0]=[o('<h2><span class="no">09</span>API 总览与约定</h2><h3>通用约定</h3><table><tr><th>项目</th><th>说明</th></tr><tr><td>基础地址</td><td><code>http://localhost:8080/api</code></td></tr><tr><td>数据格式</td><td>请求/响应均为 JSON（上传接口除外）</td></tr><tr><td>字符编码</td><td>UTF-8（中文直接传即可）</td></tr><tr><td>鉴权方式</td><td>管理接口请求头加 <code>Authorization: Bearer &lt;token&gt;</code></td></tr><tr><td>错误格式</td><td>非 2xx 时返回 <code>{&quot;error&quot;: &quot;错误原因&quot;}</code></td></tr><tr><td>token 有效期</td><td>7 天，过期后需重新登录</td></tr></table><h3>接口一览</h3><table><tr><th>方法</th><th>路径</th><th>鉴权</th><th>说明</th></tr><tr><td>POST</td><td>/api/auth/login</td><td>无</td><td>登录，拿 token</td></tr><tr><td>GET</td><td>/api/posts</td><td>无</td><td>已发布文章分页列表</td></tr><tr><td>GET</td><td>/api/posts/:id</td><td>无</td><td>文章详情</td></tr><tr><td>POST</td><td>/api/posts/:id/like</td><td>无</td><td>点赞</td></tr><tr><td>GET</td><td>/api/admin/posts</td><td>需要</td><td>全部文章（含草稿）</td></tr><tr><td>GET</td><td>/api/admin/posts/:id</td><td>需要</td><td>文章详情（含草稿）</td></tr><tr><td>POST</td><td>/api/admin/posts</td><td>需要</td><td>新建文章</td></tr><tr><td>PUT</td><td>/api/admin/posts/:id</td><td>需要</td><td>更新文章（部分字段）</td></tr><tr><td>DELETE</td><td>/api/admin/posts/:id</td><td>需要</td><td>删除文章</td></tr><tr><td>POST</td><td>/api/admin/upload</td><td>需要</td><td>上传图片</td></tr></table>',5)])])}const n=d(e,[["render",i]]);export{n as default};
